# sanity_fims ----

## Setup ----
make_mock_json_output <- function() {
  jsonlite::toJSON(list(
    fleets = list(
      list(fleet = "fleet1", module_id = 1, data_ids = list(catch = 101, age_comp = 102)),
      list(fleet = "survey1", module_id = 2, data_ids = list(index = 201))
    ),
    density_components = list(
      list(module_id = 1, input_type = "data", observed_data_id = 101, linked_ids = list(1), module_type = "lognormal"),
      list(module_id = 2, input_type = "data", observed_data_id = 102, linked_ids = list(2), module_type = "multinomial"),
      list(module_id = 3, input_type = "data", observed_data_id = 201, linked_ids = list(3), module_type = "lognormal")
    ),
    data = list(
      list(id = 101, name = "Catch"),
      list(id = 102, name = "AgeComp"),
      list(id = 201, name = "Index")
    )
  ), auto_unbox = TRUE)
}

make_mock_fit <- function(
  convergence = 0L,
  opt_message = "relative convergence (4)",
  max_gradient = 1e-5,
  gradient = c(1e-5, -5e-6),
  param_names = c("Recruitment.1.log_rzero.1", "Selectivity.1.slope.47"),
  pdHess = TRUE,
  hessian = diag(c(2, 2)),
  fixed_se = c(0.1, 0.2),
  random_se = numeric(),
  report_se = numeric(),
  optimize = TRUE,
  has_sd = TRUE,
  marginal_nll = 100,
  total_nll = 100,
  nll_components = c(10, 45, 45),
  model_output = make_mock_json_output()
) {
  mock_env <- list(
    random = if (length(random_se) > 0) seq_along(random_se) else numeric(),
    spHess = function(random = TRUE) hessian
  )

  mock_obj <- list(
    par = stats::setNames(rep(1, length(param_names)), param_names),
    fn = function(x) 0,
    gr = function(x) numeric(length(x)),
    he = function(x) hessian,
    hessian = function(x) hessian,
    method = "BFGS",
    retape = function(...) NULL,
    env = mock_env,
    report = function(...) list(),
    simulate = function(...) list()
  )

  mock_opt <- if (optimize) {
    list(
      par = stats::setNames(rep(1, length(param_names)), param_names),
      objective = marginal_nll,
      convergence = convergence,
      message = opt_message
    )
  } else {
    list()
  }

  mock_sdreport <- if (has_sd) {
    sd_list <- list(
      pdHess = pdHess,
      par.fixed = stats::setNames(rep(1, length(param_names)), param_names),
      cov.fixed = diag(fixed_se^2, nrow = length(fixed_se), ncol = length(fixed_se))
    )
    dimnames(sd_list[["cov.fixed"]]) <- list(param_names, param_names)

    if (length(random_se) > 0) {
      re_names <- paste0("re_", seq_along(random_se))
      sd_list[["par.random"]] <- stats::setNames(rep(1, length(random_se)), re_names)
      sd_list[["diag.cov.random"]] <- random_se^2
    }

    if (length(report_se) > 0) {
      rep_names <- paste0("rep_", seq_along(report_se))
      sd_list[["value"]] <- stats::setNames(rep(1, length(report_se)), rep_names)
      sd_list[["sd"]] <- report_se
    }

    structure(sd_list, class = "sdreport")
  } else {
    list()
  }

  report_list <- list(
    jnll = total_nll,
    nll_components = nll_components
  )

  methods::new(
    "FIMSFit",
    input = list(),
    obj = mock_obj,
    opt = mock_opt,
    max_gradient = if (optimize) max_gradient else NA_real_,
    gradient = if (optimize) gradient else rep(NA_real_, length(param_names)),
    report = report_list,
    sdreport = mock_sdreport,
    number_of_parameters = c(
      fixed_effects = as.integer(length(param_names)),
      random_effects = as.integer(length(random_se))
    ),
    run_time = as.difftime(1, units = "secs"),
    version = utils::packageVersion("FIMS"),
    model_output = as.character(model_output)
  )
}

## IO correctness ----
test_that("sanity_fims() works with clean converged fit", {
  #' @description Test that `sanity_fims()` reports all checks passing for a clean mock model.
  fit <- make_mock_fit()
  res <- sanity_fims(fit, verbose = FALSE)

  expect_true(is.sanity_fims(res))
  expect_identical(res[["all_ok"]], TRUE)
  expect_identical(res[["optimized"]], TRUE)
  expect_identical(res[["nlminb_ok"]], TRUE)
  expect_identical(res[["nll_ok"]], TRUE)
  expect_identical(res[["gradients_ok"]], TRUE)
  expect_identical(res[["hessian_ok"]], TRUE)
  expect_identical(res[["condition_ok"]], TRUE)
  expect_identical(res[["se_ok"]], TRUE)
  expect_identical(res[["se_na_ok"]], TRUE)
  expect_identical(res[["se_magnitude_ok"]], TRUE)
  expect_equal(length(res[["issues"]]), 0L)
  expect_equal(length(res[["warnings"]]), 0L)
})

test_that("sanity_fims() assigns descriptive names to nll_components", {
  #' @description Test that `sanity_fims()` names NLL components according to fleet and data types.
  fit <- make_mock_fit()
  res <- sanity_fims(fit, verbose = FALSE)

  expected_names <- c("fleet1_catch", "fleet1_age_comp", "survey1_index")
  expect_identical(names(res[["nll_components"]]), expected_names)
  expect_equal(res[["nll_components"]][["fleet1_catch"]], 10)
  expect_equal(res[["nll_components"]][["fleet1_age_comp"]], 45)
  expect_equal(res[["nll_components"]][["survey1_index"]], 45)
})

test_that("print.sanity_fims() outputs expected summary", {
  #' @description Test that `print.sanity_fims()` prints cleanly and returns its input invisibly.
  fit <- make_mock_fit()
  res <- sanity_fims(fit, verbose = FALSE)

  printed <- testthat::capture_messages(print_out <- print(res))
  expect_identical(print_out, res)
  expect_true(any(grepl("FIMS Model Sanity Check", printed)))
  expect_true(any(grepl("Negative log-likelihood is finite", printed)))
  expect_true(any(grepl("fleet1_catch", printed)))
  expect_true(any(grepl("All sanity checks passed", printed)))
})

## Edge handling ----
test_that("sanity_fims() flags unoptimized fit", {
  #' @description Test that `sanity_fims()` detects when a model was not optimized.
  fit <- make_mock_fit(optimize = FALSE)
  res <- sanity_fims(fit, verbose = FALSE)

  expect_identical(res[["all_ok"]], FALSE)
  expect_identical(res[["optimized"]], FALSE)
  expect_true(any(grepl("optimize = FALSE", res[["issues"]])))

  printed <- testthat::capture_messages(print(res))
  expect_true(any(grepl("Model was not optimized", printed)))
})

test_that("sanity_fims() flags non-finite marginal and total NLL", {
  #' @description Test that `sanity_fims()` detects non-finite marginal or total negative log-likelihoods.
  fit_nan_marg <- make_mock_fit(marginal_nll = NaN)
  res_nan_marg <- sanity_fims(fit_nan_marg, verbose = FALSE)
  expect_identical(res_nan_marg[["nll_ok"]], FALSE)
  expect_identical(res_nan_marg[["all_ok"]], FALSE)
  expect_true(any(grepl("Marginal negative log-likelihood is not finite", res_nan_marg[["issues"]])))

  fit_inf_total <- make_mock_fit(total_nll = Inf)
  res_inf_total <- sanity_fims(fit_inf_total, verbose = FALSE)
  expect_identical(res_inf_total[["nll_ok"]], FALSE)
  expect_identical(res_inf_total[["all_ok"]], FALSE)
  expect_true(any(grepl("Total negative log-likelihood .* is not finite", res_inf_total[["issues"]])))
})

test_that("sanity_fims() flags non-finite NLL components by name", {
  #' @description Test that `sanity_fims()` identifies non-finite NLL components by their descriptive names.
  fit <- make_mock_fit(nll_components = c(10, NaN, 45))
  res <- sanity_fims(fit, verbose = FALSE)

  expect_identical(res[["nll_ok"]], FALSE)
  expect_identical(res[["all_ok"]], FALSE)
  expect_true("fleet1_age_comp" %in% res[["details"]][["bad_nll_components"]])
  expect_true(any(grepl("fleet1_age_comp", res[["issues"]])))

  printed <- testthat::capture_messages(print(res))
  expect_true(any(grepl("Non-finite NLL component.*fleet1_age_comp", printed)))
})

test_that("sanity_fims() warns on extremely large NLL components", {
  #' @description Test that `sanity_fims()` warns when an NLL component exceeds 1e7.
  fit <- make_mock_fit(nll_components = c(10, 5e7, 45))
  res <- sanity_fims(fit, verbose = FALSE)

  expect_true(any(grepl("extremely large values.*fleet1_age_comp", res[["warnings"]])))
})

test_that("sanity_fims() warns when marginal and total NLL differ in fixed-effects model", {
  #' @description Test that `sanity_fims()` warns if marginal and total NLL differ in a fixed-effects model.
  fit <- make_mock_fit(marginal_nll = 100, total_nll = 105)
  res <- sanity_fims(fit, verbose = FALSE)

  expect_true(any(grepl("differ by.*5.*fixed-effects", res[["warnings"]])))
})

test_that("sanity_fims() flags optimizer non-convergence", {
  #' @description Test that `sanity_fims()` detects non-zero optimizer convergence codes.
  fit <- make_mock_fit(convergence = 1L, opt_message = "iteration limit reached")
  res <- sanity_fims(fit, verbose = FALSE)

  expect_identical(res[["all_ok"]], FALSE)
  expect_identical(res[["nlminb_ok"]], FALSE)
  expect_true(any(grepl("Optimizer did not converge", res[["issues"]])))
})

test_that("sanity_fims() flags moderate and high gradients", {
  #' @description Test that `sanity_fims()` flags moderate gradient (> 0.001) as warning and high gradient (> 0.01) as issue.
  fit_mod <- make_mock_fit(
    max_gradient = 0.005,
    gradient = c(0.0001, 0.005)
  )
  res_mod <- sanity_fims(fit_mod, verbose = FALSE)
  expect_identical(res_mod[["gradients_ok"]], FALSE)
  expect_identical(res_mod[["largest_gradient_parameter"]], "Selectivity.1.slope.47")
  expect_equal(length(res_mod[["warnings"]]), 1L)

  fit_high <- make_mock_fit(
    max_gradient = 0.5,
    gradient = c(0.5, 0.001)
  )
  res_high <- sanity_fims(fit_high, verbose = FALSE)
  expect_identical(res_high[["gradients_ok"]], FALSE)
  expect_identical(res_high[["largest_gradient_parameter"]], "Recruitment.1.log_rzero.1")
  expect_true(any(grepl("Maximum gradient is", res_high[["issues"]])))
})

test_that("sanity_fims() ranks and displays top 2-3 parameters with highest gradients", {
  #' @description Test that `sanity_fims()` ranks and displays the top 2-3 parameters with highest absolute gradients.
  fit <- make_mock_fit(
    param_names = c("p1", "p2", "p3", "p4"),
    gradient = c(0.001, -0.4, 0.05, -0.2),
    fixed_se = c(0.1, 0.2, 0.3, 0.4),
    max_gradient = 0.4
  )
  res <- sanity_fims(fit, verbose = FALSE)
  expect_identical(res[["gradients_ok"]], FALSE)
  expect_identical(res[["largest_gradient_parameter"]], "p2")
  expect_identical(names(res[["top_gradient_parameters"]]), c("p2", "p4", "p3"))
  expect_equal(unname(res[["top_gradient_parameters"]]), c(0.4, 0.2, 0.05))

  printed <- testthat::capture_messages(print(res))
  expect_true(any(grepl("Top gradient culprits.*p2.*p4.*p3", printed)))
})

test_that("sanity_fims() flags non-positive definite Hessian", {
  #' @description Test that `sanity_fims()` detects non-positive definite Hessian.
  fit <- make_mock_fit(pdHess = FALSE)
  res <- sanity_fims(fit, verbose = FALSE)

  expect_identical(res[["all_ok"]], FALSE)
  expect_identical(res[["hessian_ok"]], FALSE)
  expect_true(any(grepl("Hessian is not positive definite", res[["issues"]])))
})

test_that("sanity_fims() flags high condition number", {
  #' @description Test that `sanity_fims()` detects ill-conditioned Hessian.
  fit <- make_mock_fit(hessian = diag(c(1, 1e-7)))
  res <- sanity_fims(fit, verbose = FALSE)

  expect_identical(res[["all_ok"]], FALSE)
  expect_identical(res[["condition_ok"]], FALSE)
  expect_true(any(grepl("Hessian condition number", res[["warnings"]])))
})

test_that("sanity_fims() flags NA standard errors", {
  #' @description Test that `sanity_fims()` detects NA standard errors.
  fit <- make_mock_fit(fixed_se = c(0.1, NA_real_))
  res <- sanity_fims(fit, verbose = FALSE)

  expect_identical(res[["all_ok"]], FALSE)
  expect_identical(res[["se_ok"]], FALSE)
  expect_identical(res[["se_na_ok"]], FALSE)
  expect_true("Selectivity.1.slope.47" %in% res[["details"]][["na_se_parameters"]])
})

test_that("sanity_fims() flags excessively large standard errors", {
  #' @description Test that `sanity_fims()` flags parameters with standard errors exceeding big_se threshold.
  fit <- make_mock_fit(fixed_se = c(5000, 0.2))
  res <- sanity_fims(fit, big_se = 1000, verbose = FALSE)

  expect_identical(res[["all_ok"]], FALSE)
  expect_identical(res[["se_ok"]], FALSE)
  expect_identical(res[["se_magnitude_ok"]], FALSE)
  expect_true("Recruitment.1.log_rzero.1" %in% res[["details"]][["large_se_parameters"]])
})

test_that("sanity_fims() handles missing sdreport gracefully", {
  #' @description Test that `sanity_fims()` handles missing sdreport without crashing.
  fit <- make_mock_fit(has_sd = FALSE)
  res <- sanity_fims(fit, verbose = FALSE)

  expect_identical(res[["all_ok"]], FALSE)
  expect_identical(res[["hessian_ok"]], FALSE)
  expect_identical(res[["se_ok"]], FALSE)
  expect_true(any(grepl("sdreport.*missing", res[["issues"]])))
})

test_that("extract_nll_component_names() provides fallback when model_output is empty", {
  #' @description Test that `extract_nll_component_names()` falls back gracefully with missing or unparseable JSON.
  expect_identical(
    FIMS:::extract_nll_component_names("", n_components = 3),
    c("component_1", "component_2", "component_3")
  )
  expect_identical(
    FIMS:::extract_nll_component_names(NULL, n_components = 2),
    c("component_1", "component_2")
  )
})

## Error handling ----
test_that("sanity_fims() throws informative error for non-FIMSFit objects", {
  #' @description Test that `sanity_fims()` aborts with an error when called on unsupported objects.
  expect_error(
    sanity_fims("not_a_model"),
    regexp = "No.*sanity_fims.*method for object of class"
  )
})
